-- Re-seeds the `podcast_episode` kind after PodcastEpisodeOutput gained the
-- media identities behind its URLs (audio_file_id / image_file_ids /
-- video_file_ids / official_video_file_id).
--
-- WHY: the podcast pipeline is URL-shaped end to end — every stage output is a
-- string — so the episode payload carried links and nothing else. But every one
-- of those URLs is one WE minted, and our object keys carry the cld_files id, so
-- the identity was recoverable all along (matrx_files.file_id_from_our_url). A
-- consumer of an episode can now re-mint a URL instead of holding one that dies.
-- Supersedes the schema seeded by content_ir_seed_podcast_episode_kind.sql,
-- which is left untouched as the record of what landed then.
--
-- Guarded, not unconditional: a no-op when the row already holds this shape.

update content_ir.kind_definition
   set emitted_json_schema = $mtx${"$defs": {"PodcastSpeaker": {"description": "One resolved cast member \u2014 mirrors ``SpeakerSpec.model_dump()``\n(matrx_ai.agent_runners.podcast_generator.SpeakerSpec), which is exactly\nwhat ``PodcastCompleteEvent.speakers`` carries.", "properties": {"name": {"description": "Resolved speaker display name.", "title": "Name", "type": "string"}, "voice": {"default": "", "description": "Resolved provider voice id used for this speaker.", "title": "Voice", "type": "string"}, "gender": {"default": "", "description": "Resolved gender label used for cast and voice matching.", "title": "Gender", "type": "string"}}, "required": ["name"], "title": "PodcastSpeaker", "type": "object"}}, "additionalProperties": false, "description": "Success payload (Node Result System) \u2014 mirrors the terminal\n``PodcastCompleteEvent`` minus the reserved envelope fields\n(``success``/``error`` \u2014 a failed generation is a node Failure with\ncode ``generation_failed``) and the stream ``type`` discriminator.", "properties": {"show_id": {"description": "Podcast show containing the generated episode.", "title": "Show Id", "type": "string"}, "episode_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Persisted pc_episodes id, or null if persistence did not complete.", "title": "Episode Id"}, "episode_slug": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Public episode slug, or null if persistence did not complete.", "title": "Episode Slug"}, "script": {"default": "", "description": "Final speaker-labeled episode script.", "title": "Script", "type": "string"}, "audio_url": {"default": "", "description": "Durable public URL of the generated episode audio.", "title": "Audio Url", "type": "string"}, "title": {"default": "", "description": "Generated episode title.", "title": "Title", "type": "string"}, "description": {"default": "", "description": "Generated episode description.", "title": "Description", "type": "string"}, "image_urls": {"description": "Durable public URLs of supporting generated images.", "items": {"type": "string"}, "title": "Image Urls", "type": "array"}, "video_urls": {"description": "Durable public URLs of supporting generated video clips.", "items": {"type": "string"}, "title": "Video Urls", "type": "array"}, "official_video_url": {"default": "", "description": "Durable public URL of the composed official episode video.", "title": "Official Video Url", "type": "string"}, "audio_file_id": {"default": "", "description": "cld_files id of the episode audio \u2014 the durable handle. Empty when the audio is not one of our files.", "title": "Audio File Id", "type": "string"}, "image_file_ids": {"description": "cld_files ids paired positionally with image_urls; \"\" where the id is not recoverable.", "items": {"type": "string"}, "title": "Image File Ids", "type": "array"}, "video_file_ids": {"description": "cld_files ids paired positionally with video_urls; \"\" where the id is not recoverable.", "items": {"type": "string"}, "title": "Video File Ids", "type": "array"}, "official_video_file_id": {"default": "", "description": "cld_files id of the composed official episode video, when it is ours.", "title": "Official Video File Id", "type": "string"}, "official_video_error": {"default": "", "description": "Composition error when the official video could not be produced.", "title": "Official Video Error", "type": "string"}, "host_count": {"default": 2, "description": "Number of speakers in the resolved cast.", "title": "Host Count", "type": "integer"}, "speakers": {"description": "Resolved cast in speaking-priority order.", "items": {"$ref": "#/$defs/PodcastSpeaker"}, "title": "Speakers", "type": "array"}}, "required": ["show_id"], "title": "PodcastEpisodeOutput", "type": "object"}$mtx$::jsonb
 where organization_id = '39c38960-d30c-4840-b0c1-c9960de95582'
   and kind = 'podcast_episode'
