ion.", "title": "Description", "type": "string"}, "image_urls": {"description": "Durable public URLs of supporting generated images.", "items": {"type": "string"}, "title": "Image Urls", "type": "array"}, "video_urls": {"description": "Durable public URLs of supporting generated video clips.", "items": {"type": "string"}, "title": "Video Urls", "type": "array"}, "official_video_url": {"default": "", "description": "Durable public URL of the composed official episode video.", "title": "Official Video Url", "type": "string"}, "audio_file_id": {"default": "", "description": "cld_files id of the episode audio \u2014 the durable handle. Empty when the audio is not one of our files.", "title": "Audio File Id", "type": "string"}, "image_file_ids": {"description": "cld_files ids paired positionally with image_urls; \"\" where the id is not recoverable.", "items": {"type": "string"}, "title": "Image File Ids", "type": "array"}, "video_file_ids": {"description": "cld_files ids paired positionally with video_urls; \"\" where the id is not recoverable.", "items": {"type": "string"}, "title": "Video File Ids", "type": "array"}, "official_video_file_id": {"default": "", "description": "cld_files id of the composed official episode video, when it is ours.", "title": "Official Video File Id", "type": "string"}, "official_video_error": {"default": "", "description": "Composition error when the official video could not be produced.", "title": "Official Video Error", "type": "string"}, "host_count": {"default": 2, "description": "Number of speakers in the resolved cast.", "title": "Host Count", "type": "integer"}, "speakers": {"description": "Resolved cast in speaking-priority order.", "items": {"$ref": "#/$defs/PodcastSpeaker"}, "title": "Speakers", "type": "array"}}, "required": ["show_id"], "title": "PodcastEpisodeOutput", "type": "object"}$mtx$::jsonb;
